object ServiceRegistry {
    private val services = ConcurrentHashMap<String, () -> Any>()
    fun register(name: String, factory: () -> Any) {
        require(services.putIfAbsent(name, factory) == null) {
            "duplicate service: $name"
        }
    }
    @Suppress("UNCHECKED_CAST")
    fun <T : Any> lookup(name: String): T =
        (services[name]?.invoke() as? T) ?: error("unknown service: $name")
}
